#include "engine_registry.hpp"

#include <algorithm>
#include <cstdlib>
#include <filesystem>
#include <fstream>
#include <set>
#include <sstream>

#include <unistd.h>

#include "config_env.hpp"
#include "json.hpp"
#include "process.hpp"
#include "repo_root.hpp"

namespace fs = std::filesystem;

namespace andes_sim {

// The bundled functional engine(s). QEMU does not implement --describe, so the
// descriptor is built in. builtin_qemu_arch(64) is the rv64 "qemu64";
// builtin_qemu_arch(32) is the rv32 "qemu32" (qemu-system-riscv32). The
// standalone (model=fast) run uses qemu's OWN default -cpu -- the user's post-`--`
// args (incl. an explicit -cpu) still win; only the rv64 hybrid fast-leg pins a
// -cpu. Binary path honors $VSIM_QEMU / $VSIM_QEMU32, then $QEMU_BIN_DIR (env or
// config.env), then the legacy in-tree build. Exposed (engine_registry.hpp) so
// `run --mode fast` resolves qemu directly, skipping the per-engine --describe
// scan whole-registry discovery would spawn.
EngineDescriptor builtin_qemu_arch(int xlen) {
  const bool rv32 = (xlen == 32);
  EngineDescriptor d;
  d.id = rv32 ? kQemuId32 : kQemuId64;
  d.type = "qemu";
  d.kind = "functional";
  d.xlen = xlen;
  d.triggers = {"marker", "pc"};
  d.state = {"drain"};
  d.source = "built-in";

  d.roles = {"standalone"};
  if (!rv32) {  // hybrid rv32 (qemu32 fast-leg + engine-matched -cpu) not wired yet
    // The hybrid fast-forward leg (rv64): load the ELF, drain on the plugin's
    // trigger into {state_out}, exit 200. {plugin}/{mmap}/{mmap_size}/{state_out}
    // are filled by the plan executor (F6); {trigger} is the plugin comma-suffix
    // (empty for marker), folded by leg_trigger_args (F9).
    d.roles.push_back("fast-leg");
    // {qemu_cpu}: the accurate engine's CPU model (from its --print-qemu-config
    // driver globals; run_plan falls back to the andes-ax45mpv family default).
    // The -readconfig globals apply only to the driver they name, so the model
    // must follow the engine -- andes-ax45mpv silently kept vlen=512 when the
    // ax66 (VLEN 128) pairing asked for 128.
    d.invoke.push_back(
        {"fast-leg",
         {"{bin}", "-object",
          "memory-backend-file,id=mem,share=on,mem-path={mmap},size={mmap_size}",
          "-machine", "andes_ae350,memory-backend=mem", "-cpu",
          "{qemu_cpu},vlen={vlen}", "-nographic", "-semihosting-config",
          "enable=on,target=native", "-bios", "{elf}", "-plugin",
          "{plugin},outfile={state_out}{trigger}"}});
  }

  // The standalone functional run (model=fast). andes_ae350's generic default
  // -cpu hangs the vplat fixtures, so pin a concrete andes core: the
  // vector-capable andes-ax46mpv (rv64) / andes-a46mpv (rv32). We pass NO vlen --
  // the cpu model's own QEMU default applies, so both scalar and vector binaries
  // run out of the box; a user who needs a specific width passes it via the
  // post-`--` -cpu (e.g. -cpu andes-ax46mpv,vlen=512), which still wins.
  // run_passthrough fills {bin}/{elf}.
  const char* fast_cpu = rv32 ? "andes-a46mpv" : "andes-ax46mpv";
  d.invoke.push_back(
      {"standalone",
       {"{bin}", "-machine", "andes_ae350", "-cpu", fast_cpu, "-nographic",
        "-semihosting-config", "enable=on,target=native", "-bios", "{elf}"}});

  const std::string sys =
      std::string("qemu-system-") + (rv32 ? "riscv32" : "riscv64");
  const char* env = rv32 ? "VSIM_QEMU32" : "VSIM_QEMU";
  if (const char* q = std::getenv(env); q && *q)
    d.bin_path = q;
  else if (std::string qd = config_env_value("QEMU_BIN_DIR"); !qd.empty())
    d.bin_path = (fs::path(qd) / sys).string();
  else
    d.bin_path = (repo_root() / "build" / "qemu" / sys).string();
  return d;
}

// rv64 qemu (back-compat: the default functional engine and hybrid fast leg).
EngineDescriptor builtin_qemu() { return builtin_qemu_arch(64); }

namespace {

constexpr int kDescribeTimeoutMs = 5000;

bool is_executable_file(const fs::path& p) {
  std::error_code ec;
  if (!fs::is_regular_file(p, ec)) return false;
  return ::access(p.c_str(), X_OK) == 0;
}

std::string read_file(const fs::path& p) {
  std::ifstream f(p, std::ios::binary);
  std::ostringstream ss;
  ss << f.rdbuf();
  return ss.str();
}

// Ask one binary to describe itself: try `<bin> --describe`, else read the
// <bin>.json sidecar. On success fills `d` and returns true; on failure leaves
// a human-readable note in `warn`.
bool describe_one(const fs::path& bin, EngineDescriptor& d, std::string& warn) {
  RunResult r = run_process({bin.string(), "--describe"}, kDescribeTimeoutMs);
  if (!r.spawn_failed && !r.timed_out && r.rc == 0) {
    json::Parsed p = json::parse(r.out);
    if (p.ok) {
      std::string err = descriptor_from_json(p.value, d);
      if (err.empty()) {
        d.bin_path = bin.string();
        d.source = "--describe";
        return true;
      }
      warn = bin.string() + ": --describe JSON invalid: " + err;
    } else {
      warn = bin.string() + ": --describe output is not JSON: " + p.error;
    }
  }

  fs::path sidecar = bin;
  sidecar += ".json";
  std::error_code ec;
  if (fs::exists(sidecar, ec)) {
    json::Parsed p = json::parse(read_file(sidecar));
    if (p.ok) {
      EngineDescriptor sd;
      std::string err = descriptor_from_json(p.value, sd);
      if (err.empty()) {
        sd.bin_path = bin.string();
        sd.source = "sidecar";
        d = std::move(sd);
        return true;
      }
      warn = sidecar.string() + ": invalid descriptor: " + err;
    } else {
      warn = sidecar.string() + ": not JSON: " + p.error;
    }
  }

  if (warn.empty()) warn = bin.string() + ": no --describe and no sidecar";
  return false;
}

// `prefix` filters candidate basenames; empty accepts any executable. The
// default VSIM_BIN_DIR scan passes "sim_"; a user-curated engines dir passes
// "" so a drop-in alioth/sid (any name) is eligible. The naming convention thus
// lives in the call site, not in this engine-agnostic scanner.
void scan_dir(const fs::path& dir, std::string_view prefix, Discovery& out,
              std::set<std::string>& seen) {
  std::error_code ec;
  if (!fs::is_directory(dir, ec)) return;

  std::vector<fs::path> entries;
  for (const auto& e : fs::directory_iterator(dir, ec)) entries.push_back(e.path());
  std::sort(entries.begin(), entries.end());  // stable, deterministic order

  for (const fs::path& p : entries) {
    if (!prefix.empty() && !p.filename().string().starts_with(prefix)) continue;
    if (!is_executable_file(p)) continue;
    EngineDescriptor d;
    std::string warn;
    if (describe_one(p, d, warn)) {
      normalize_engine_label(d);  // verilator -> vsim, before dedup keys on id
      if (seen.insert(d.id).second) out.engines.push_back(std::move(d));
    } else if (!warn.empty()) {
      out.warnings.push_back(warn);
    }
  }
}

}  // namespace

// See engine_registry.hpp. VSIM_BIN_DIR (the external prebuilt vsim build,
// mirroring QEMU_BIN_DIR) resolved env-first then from config.env, so the driver
// finds the external vsim without a prior `source ./setup.sh`. Empty when
// unset everywhere -- there is no in-tree vsim to fall back to.
fs::path vsim_scan_dir(const fs::path& config_file) {
  return config_env_value("VSIM_BIN_DIR", config_file);
}

fs::path vsim_scan_dir() {
  return vsim_scan_dir(repo_root() / "config.env");
}

Discovery discover_engines() {
  Discovery out;
  std::set<std::string> seen;

  EngineDescriptor qemu = builtin_qemu();
  seen.insert(qemu.id);
  out.engines.push_back(std::move(qemu));

  // rv32 functional engine, listed alongside qemu so `list engines` shows both
  // (its binary is qemu-system-riscv32 under the same QEMU_BIN_DIR).
  EngineDescriptor qemu32 = builtin_qemu_arch(32);
  seen.insert(qemu32.id);
  out.engines.push_back(std::move(qemu32));

  if (const char* env = std::getenv("ANDESIM_ENGINES_DIR"); env && *env) {
    std::stringstream ss(env);
    std::string dir;
    while (std::getline(ss, dir, ':'))
      if (!dir.empty()) scan_dir(dir, /*prefix=*/"", out, seen);
  } else {
    scan_dir(vsim_scan_dir(), /*prefix=*/"sim_", out, seen);
  }
  return out;
}

}  // namespace andes_sim

// ELF symbol resolution for pc-trigger boundaries (F9).
//
// pc mode switches QEMU <-> vsim at two PCs. Either boundary may be a
// "0x"-prefixed hex address (used verbatim) OR a symbol defined in the ELF
// (resolved against its .symtab). This decouples the switch points from the
// workload source -- any function can bound the ROI, with no planted markers.
//
// C++ port of tests/lib/roi.sh:resolve_pc, reading the ELF .symtab directly via
// <elf.h> rather than shelling out to `nm`.
#ifndef ANDESIM_ELF_SYMS_HPP
#define ANDESIM_ELF_SYMS_HPP

#include <cstdint>
#include <string>

namespace andes_sim {

// Resolve a pc-mode boundary to a bare hex address string (no "0x" prefix).
//   "0x<h>" / "0X<h>"  -> "<h>" verbatim (prefix stripped, digits unchanged)
//   <symbol>           -> the symbol's st_value as lowercase hex
// On any failure (undefined symbol, unreadable/!ELF file) returns "" and sets
// `err` to a message naming the boundary; on success leaves `err` empty.
std::string resolve_pc(const std::string& elf_path, const std::string& boundary,
                       std::string& err);

// The ELF class width in bits from e_ident[EI_CLASS]: 32 (ELFCLASS32) or 64
// (ELFCLASS64). Returns 0 when `elf_path` is unreadable or not an ELF. Reads
// only the 16-byte e_ident (the class-independent prefix), so it answers for
// rv32 and rv64 alike -- the source of truth for the fast auto-pick of
// qemu-system-riscv32/64 and the cycle/hybrid arch-match guard.
int elf_xlen(const std::string& elf_path);

// L26/F3: the highest byte of the ELF's static memory image -- the maximum
// (p_paddr + p_memsz) over PT_LOAD segments. The driver rejects a hybrid run
// when this exceeds the V-scratch GPA (ram_base + --mem-size): the static image
// would extend into the reserved transport page above the program's RAM.
// Returns 0 + err on an unreadable / non-ELFCLASS64 file; 0 with empty err when
// the ELF has no loadable segments (nothing to clash with the scratch).
uint64_t elf_load_top(const std::string& elf_path, std::string& err);

// Reverse lookup: the nearest function symbol at or below `addr`, formatted
// "name+0xoff" (or just "name" at offset 0). Returns "" when no covering
// function symbol is found or the ELF is unreadable -- the caller always has
// the raw pc to fall back on, so this never errors.
std::string symbolize(const std::string& elf_path, uint64_t addr);

// Returns {st_value, st_value + st_size} for the FUNC symbol covering `addr`.
// Both members are 0 when not found or unreadable.
std::pair<uint64_t, uint64_t> fn_range(const std::string& elf_path, uint64_t addr);

}  // namespace andes_sim

#endif  // ANDESIM_ELF_SYMS_HPP

// Subprocess helpers for andesim.
//
// run_process spawns a child, captures its stdout, and kills it after a
// timeout -- the primitive the engine registry uses to ask `<bin> --describe`
// and the plan executor (F6) uses to run orchestrated legs. F5 extends this
// file with exec_passthrough (inherit stdio, no timeout) for fast/cycle.
#ifndef ANDESIM_PROCESS_HPP
#define ANDESIM_PROCESS_HPP

#include <functional>
#include <string>
#include <string_view>
#include <vector>

namespace andes_sim {

struct RunResult {
  int rc = -1;                // child exit status, or -1 if killed/abnormal
  std::string out;            // captured stdout
  bool timed_out = false;     // killed because it exceeded the timeout
  bool spawn_failed = false;  // pipe/fork failed before the child ran
};

// Run argv (argv[0] resolved via PATH), capturing stdout. The child's stdin
// is redirected to /dev/null; stderr too, unless relay_stderr is set, in
// which case the child inherits OUR stderr and its diagnostics stream live
// (used to surface the legs' leveled logs at --log-level <= debug). If the
// child runs longer than timeout_ms it is SIGKILLed and timed_out is set.
RunResult run_process(const std::vector<std::string>& argv, int timeout_ms,
                      bool relay_stderr = false);

// Run argv to completion with the child INHERITING all three std streams
// (stdin, stdout, stderr) -- the transparent-passthrough mechanism behind
// `run --mode fast|cycle`: the engine reads/writes the terminal directly,
// so an interactive gdbstub or semihosting console works unchanged. No chdir,
// no capture, no timeout. Returns the child's exit code, 128+signal if it was
// signalled, or -1 on spawn failure / empty argv.
int exec_passthrough(const std::vector<std::string>& argv);

// Fork a child that execs argv with inherited stdio and return immediately
// without waiting. Used by `run --mode cycle --gdb` to launch vsim in the
// background before exec-ing ICEman in the foreground. Returns the child pid
// on success, -1 on empty argv or fork failure.
int fork_background(const std::vector<std::string>& argv);

// Run argv with BOTH stdout and stderr captured (separate pipes) and stdin
// inherited, streaming each complete line to `on_line(stream, line)` as it
// arrives -- stream is 1 (stdout) or 2 (stderr), line excludes the trailing
// newline. The callback owns presentation (it decides what to write to the real
// streams), so this is the filtered counterpart to exec_passthrough: same "run
// to completion, no timeout, propagate exit code" contract, but the parent sees
// every line. A final unterminated line is delivered too. Returns the child's
// exit code, 128+signal if signalled, or -1 on spawn failure / empty argv.
int run_line_filtered(
    const std::vector<std::string>& argv,
    const std::function<void(int stream, std::string_view line)>& on_line);

}  // namespace andes_sim

#endif  // ANDESIM_PROCESS_HPP

